/** Clear a discharge stage (in order) — POST /api/v1/admissions/{admission_id}/discharge/{stage}/clear (who may call: the permission of the stage: ipd.discharge.clear_pharmacy, clear_nursing, clear_billing or clear_cleaning). */
export function clearStage(admission_id: number, stage: "PharmacyClearance" | "NursingMARVerification" | "BillingSettlement" | "OpsCleaning", body: ClearIn): Promise<AdmissionDetailOut> {
  return api<AdmissionDetailOut>("POST", `/admissions/${admission_id}/discharge/${stage}/clear`, body);
}

/** Medication Administration Record (checklist) — GET /api/v1/admissions/{admission_id}/mar (who may call: holders of ipd.mar.view). */
export function mar(admission_id: number): Promise<MarEntryOut[]> {
  return api<MarEntryOut[]>("GET", `/admissions/${admission_id}/mar`, undefined);
}

/** Chart a scheduled dose (Administered / Held / Refused / Missed) — POST /api/v1/mar/{mar_id}/chart (who may call: holders of ipd.mar.administer). */
export function chart(mar_id: number, body: ChartIn): Promise<MarRecordOut> {
  return api<MarRecordOut>("POST", `/mar/${mar_id}/chart`, body);
}

/** Chart a PRN / ad-hoc dose — POST /api/v1/admissions/{admission_id}/mar/prn (who may call: holders of ipd.mar.administer). */
export function prn(admission_id: number, body: PrnIn): Promise<MarRecordOut> {
  return api<MarRecordOut>("POST", `/admissions/${admission_id}/mar/prn`, body, { idempotent: true });
}

/** Correction entry for a charted dose — POST /api/v1/mar/{mar_id}/correction (who may call: holders of ipd.mar.administer). */
export function marCorrection(mar_id: number, body: MarCorrectionIn): Promise<MarRecordOut> {
  return api<MarRecordOut>("POST", `/mar/${mar_id}/correction`, body, { idempotent: true });
}

/** Generate scheduled doses from active IPD orders (idempotent) — POST /api/v1/admissions/{admission_id}/mar/generate (who may call: holders of ipd.mar.administer or prescription.create). */
export function marGenerate(admission_id: number): Promise<MarGenerateOut> {
  return api<MarGenerateOut>("POST", `/admissions/${admission_id}/mar/generate`, undefined);
}

/** Ward-local stock — GET /api/v1/wards/{ward_id}/inventory (who may call: holders of ward.inventory.view). */
